package cn.yuanxin.mvp.web.mediapolicy;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.auth.PrincipalType;
import cn.yuanxin.mvp.web.config.AppProperties;
import cn.yuanxin.mvp.web.media.AllowAuthenticatedMediaAccessPolicy;
import cn.yuanxin.mvp.web.media.MediaAccessPolicy;
import cn.yuanxin.mvp.web.media.MediaObject;
import cn.yuanxin.mvp.web.media.MediaPurpose;
import cn.yuanxin.mvp.web.media.OwnerBasedMediaAccessPolicy;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

import java.util.EnumSet;
import java.util.Set;
import java.util.UUID;

/**
 * B 包统一业务媒体授权策略（DD 10.2 五步判定 / DD 4.3 图片权限行）。
 *
 * <p><b>唯一业务策略</b>：{@code @Primary} 覆盖 A 的生产安全默认 deny-all。
 * {@code false} 会被 A 的 {@link cn.yuanxin.mvp.web.media.MediaController}
 * 转成与"资源不存在"<b>完全一致</b>的 404 {@code RESOURCE_NOT_VISIBLE}——本策略
 * 只返回布尔，绝不抛 403、绝不制造可区分错误。</p>
 *
 * <p>判定顺序（全部单表查询，无 JOIN、无关联子查询，每请求至多 3 条 SELECT）：</p>
 * <ol>
 *   <li><b>face 用途黑名单（最先、无条件）</b>：{@code grant_face} /
 *       {@code execution_face} / {@code revalidation_face} 对任何主体一律拒绝
 *       （上传者、有 active T02 的账号、当前任务云台都不例外）；dev/test 便利
 *       模式也<b>永不委派</b> face 用途。</li>
 *   <li><b>状态与接纳</b>：{@code state != 'available'} → 拒绝；单表读 T11
 *       {@code media_objects} 取归属列（接口 {@code MediaObject} 不含归属），
 *       {@code assessment_id IS NULL}（available 但未被业务接纳）→ 拒绝。</li>
 *   <li><b>冻结报告公开引用（必要条件，APP/云台都适用）</b>：单表读 T05
 *       {@code skin_assessments}，要求 {@code status='report_ready'} 且
 *       {@code report_id/report_payload/report_photo_version} 非空，且该
 *       mediaId 被报告公开投影显式引用（见 "公开引用约定"）。</li>
 *   <li><b>主体分支</b>：APP 单表读 T02 {@code member_access_grants}
 *       ({@code account_id=principal.accountUuid()}，成员取 T11.member_id，
 *       回退 T05.member_id，均空则拒绝) 要求 {@code status='active'}；撤销即时
 *       生效（无缓存）。GIMBAL 单表读 T03 {@code gimbals}，要求
 *       {@code current_assessment_id == media.assessment_id}（仅自己的当前任务）
 *       且 {@code credential_version == principal.credentialVersion()}。云台绑定
 *       不能替代成员授权（SC-05-07）。</li>
 * </ol>
 *
 * <p><b>公开引用约定（{@code report_payload} 形状未冻结，deny-by-default）</b>：
 * 仅当下列任一位置显式把该 mediaId 标为公开展示图时才算被引用：</p>
 * <ul>
 *   <li>{@code report_payload.public_media_ids} 数组中含该 mediaId（UUID 字符串）；或</li>
 *   <li>{@code report_payload.photos[]} / {@code report_payload.images[]} 中某项的
 *       {@code media_id}/{@code mediaId} 等于该 mediaId 且该项 {@code public} 为
 *       JSON 布尔 {@code true}；或</li>
 *   <li>T05 {@code photo_versions}（数组或对象）中某项的 {@code media_id}/{@code mediaId}
 *       等于该 mediaId 且 {@code public} 为 {@code true}（{@code version} 与
 *       {@code report_photo_version} 一致时优先采信）。</li>
 * </ul>
 * <p>缺键、{@code public} 缺失/false、类型不符、解析失败一律拒绝；解析异常只记
 * 一条不含内容的 warn 日志（仅 mediaId 与分支名），绝不抛到控制器变成 500。
 * 该约定通过协调条目 C10 请 C/D 确认或替换，本策略不为此改契约或迁移。</p>
 *
 * <p><b>dev/test 便利模式委派</b>：A 的模式 bean 由
 * {@code @ConditionalOnMissingBean} 保护，本 @Primary bean 存在时会退让，因此
 * 在<b>非 production 且显式配置 owner-dev / any-authenticated</b> 时，对非 face
 * 用途且业务判定为 false 的情况委派给对应便利策略（优先复用容器内已注册的 A
 * 策略 bean，缺失则按配置构造），以保持 A 既有媒体测试行为。production 或默认
 * deny-all 下<b>绝不委派</b>，只有第 1–4 条业务判定。</p>
 *
 * <p>只读、无副作用：不写任何表、不递增 revision、不缓存授权结果（撤销即时生效）。
 * 日志不输出 bucket/object_key/成员 ID。</p>
 */
@Component
@Primary
public class BusinessMediaAccessPolicy implements MediaAccessPolicy {

    private static final Logger log = LoggerFactory.getLogger(BusinessMediaAccessPolicy.class);

    private static final Set<MediaPurpose> FACE_PURPOSES = EnumSet.of(
            MediaPurpose.GRANT_FACE,
            MediaPurpose.EXECUTION_FACE,
            MediaPurpose.REVALIDATION_FACE);

    private final JdbcTemplate jdbc;
    private final ObjectMapper objectMapper;
    private final AppProperties appProperties;
    private final ApplicationContext applicationContext;

    private volatile MediaAccessPolicy devDelegate;
    private volatile boolean devDelegateResolved;

    public BusinessMediaAccessPolicy(JdbcTemplate jdbc, ObjectMapper objectMapper,
                                     AppProperties appProperties,
                                     ApplicationContext applicationContext) {
        this.jdbc = jdbc;
        this.objectMapper = objectMapper;
        this.appProperties = appProperties;
        this.applicationContext = applicationContext;
    }

    @Override
    public boolean canAccess(PrincipalContext principal, MediaObject media) {
        if (principal == null || media == null) {
            return false;
        }
        // 规则 1：face 用途 / 未知用途先拒绝，且永不委派。
        boolean neverDelegatable = media.purpose() == null
                || FACE_PURPOSES.contains(media.purpose());
        boolean allowed;
        try {
            allowed = decide(principal, media);
        } catch (RuntimeException e) {
            // fail closed：任何 DB/解析异常都表现为不可见（404），绝不 500。
            log.warn("media policy decision failed closed mediaId={} branch=error", media.id());
            allowed = false;
        }
        if (allowed) {
            return true;
        }
        if (neverDelegatable) {
            return false;
        }
        MediaAccessPolicy delegate = devDelegate();
        if (delegate == null) {
            return false;
        }
        try {
            return delegate.canAccess(principal, media);
        } catch (RuntimeException e) {
            log.warn("media policy dev delegation failed closed mediaId={} branch=delegate-error",
                    media.id());
            return false;
        }
    }

    /** 规则 2–4（不含 dev 便利委派）。 */
    private boolean decide(PrincipalContext principal, MediaObject media) {
        // 规则 2：状态必须 available（控制器已挡；策略自身也挡，防他处复用）。
        if (!"available".equals(media.state())) {
            return false;
        }
        // 规则 2：单表读 T11 归属列（接口投影不含 assessment/member/photo_version）。
        var mediaRows = jdbc.query(
                "SELECT assessment_id, photo_version, member_id FROM media_objects WHERE id = ?",
                (rs, i) -> new MediaAttribution(
                        rs.getObject("assessment_id", UUID.class),
                        rs.wasNull() ? null : rs.getObject("photo_version", Long.class),
                        rs.getObject("member_id", UUID.class)),
                media.id());
        if (mediaRows.isEmpty()) {
            return false;
        }
        MediaAttribution attribution = mediaRows.get(0);
        // available 但未被业务接纳（无测肤任务归属）→ 拒绝。
        if (attribution.assessmentId() == null) {
            return false;
        }
        // 规则 3：单表读 T05 冻结报告（status/report_id/report_payload/report_photo_version）。
        var assessmentRows = jdbc.query(
                "SELECT status, report_id, report_payload::text AS report_payload,"
                        + " report_photo_version, photo_versions::text AS photo_versions, member_id"
                        + " FROM skin_assessments WHERE id = ?",
                (rs, i) -> new AssessmentProjection(
                        rs.getString("status"),
                        rs.getObject("report_id", UUID.class),
                        rs.getString("report_payload"),
                        rs.wasNull() ? null : rs.getObject("report_photo_version", Long.class),
                        rs.getString("photo_versions"),
                        rs.getObject("member_id", UUID.class)),
                attribution.assessmentId());
        if (assessmentRows.isEmpty()) {
            return false;
        }
        AssessmentProjection assessment = assessmentRows.get(0);
        if (!"report_ready".equals(assessment.status())
                || assessment.reportId() == null
                || assessment.reportPayload() == null
                || assessment.reportPhotoVersion() == null) {
            return false;
        }
        if (!isPubliclyReferenced(assessment, media.id())) {
            return false;
        }
        // 规则 4：主体分支。
        if (principal.principalType() == PrincipalType.APP) {
            UUID memberId = attribution.memberId() != null
                    ? attribution.memberId() : assessment.memberId();
            if (memberId == null || principal.accountUuid() == null) {
                return false;
            }
            Integer active = jdbc.queryForObject(
                    "SELECT count(*) FROM member_access_grants"
                            + " WHERE account_id = ? AND member_id = ? AND status = 'active'",
                    Integer.class, principal.accountUuid(), memberId);
            return active != null && active > 0;
        }
        if (principal.principalType() == PrincipalType.GIMBAL) {
            if (principal.gimbalUuid() == null) {
                return false;
            }
            var gimbalRows = jdbc.query(
                    "SELECT current_assessment_id, credential_version FROM gimbals WHERE id = ?",
                    (rs, i) -> new GimbalProjection(
                            rs.getObject("current_assessment_id", UUID.class),
                            rs.getLong("credential_version")),
                    principal.gimbalUuid());
            if (gimbalRows.isEmpty()) {
                return false;
            }
            GimbalProjection gimbal = gimbalRows.get(0);
            // 只限自己的当前任务 + 凭据代次一致（云台不得借历史任务/Member 扩大范围）。
            return attribution.assessmentId().equals(gimbal.currentAssessmentId())
                    && gimbal.credentialVersion() == principal.credentialVersion();
        }
        return false;
    }

    // ------------------------------------------------------------------
    // 公开引用读取（宽容 + 默认拒绝）
    // ------------------------------------------------------------------

    private boolean isPubliclyReferenced(AssessmentProjection assessment, UUID mediaId) {
        try {
            JsonNode payload = objectMapper.readTree(assessment.reportPayload());
            if (payload != null && payload.isObject()) {
                if (containsMediaId(payload.get("public_media_ids"), mediaId)) {
                    return true;
                }
                if (hasPublicEntry(payload.get("photos"), mediaId)) {
                    return true;
                }
                if (hasPublicEntry(payload.get("images"), mediaId)) {
                    return true;
                }
            }
            if (assessment.photoVersions() != null) {
                JsonNode versions = objectMapper.readTree(assessment.photoVersions());
                if (hasPublicEntry(versions, mediaId)) {
                    return true;
                }
            }
        } catch (Exception e) {
            // 解析失败 → 拒绝（deny-by-default），只记 mediaId，不含任何 payload 内容。
            log.warn("media policy public-reference parse failed; denied mediaId={}", mediaId);
            return false;
        }
        return false;
    }

    /** {@code [uuid, ...]}：元素需为文本 UUID。 */
    private static boolean containsMediaId(JsonNode arrayNode, UUID mediaId) {
        if (arrayNode == null || !arrayNode.isArray()) {
            return false;
        }
        for (JsonNode element : arrayNode) {
            if (element.isTextual() && uuidEquals(element.asText(), mediaId)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 数组（或对象的值集合）中每项：{@code media_id}/{@code mediaId} == id
     * 且 {@code public} 为 JSON 布尔 {@code true}（字符串 "true" 视为类型不符 → 拒绝）。
     */
    private static boolean hasPublicEntry(JsonNode node, UUID mediaId) {
        if (node == null || node.isNull()) {
            return false;
        }
        if (node.isArray()) {
            for (JsonNode element : node) {
                if (isPublicEntry(element, mediaId)) {
                    return true;
                }
            }
            return false;
        }
        if (node.isObject()) {
            for (JsonNode element : node) {
                if (isPublicEntry(element, mediaId)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isPublicEntry(JsonNode element, UUID mediaId) {
        if (element == null || !element.isObject()) {
            return false;
        }
        UUID entryId = firstMediaId(element);
        if (entryId == null || !entryId.equals(mediaId)) {
            return false;
        }
        JsonNode publicFlag = element.get("public");
        return publicFlag != null && publicFlag.isBoolean() && publicFlag.booleanValue();
    }

    private static UUID firstMediaId(JsonNode element) {
        UUID id = parseUuid(element.get("media_id"));
        return id != null ? id : parseUuid(element.get("mediaId"));
    }

    private static UUID parseUuid(JsonNode node) {
        if (node == null || !node.isTextual()) {
            return null;
        }
        try {
            return UUID.fromString(node.asText());
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    private static boolean uuidEquals(String text, UUID expected) {
        UUID parsed = parseUuidText(text);
        return parsed != null && parsed.equals(expected);
    }

    private static UUID parseUuidText(String text) {
        if (text == null) {
            return null;
        }
        try {
            return UUID.fromString(text);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    // ------------------------------------------------------------------
    // dev/test 便利模式委派（非 production；face 永不委派）
    // ------------------------------------------------------------------

    private MediaAccessPolicy devDelegate() {
        if (devDelegateResolved) {
            return devDelegate;
        }
        synchronized (this) {
            if (!devDelegateResolved) {
                devDelegate = resolveDevDelegate();
                devDelegateResolved = true;
            }
            return devDelegate;
        }
    }

    private MediaAccessPolicy resolveDevDelegate() {
        // production 或默认 deny-all：绝不委派。
        if ("production".equals(appProperties.env())) {
            return null;
        }
        AppProperties.Media media = appProperties.media();
        boolean anyAuthenticated = media.allowAnyAuthenticated()
                || AppProperties.MEDIA_MODE_ANY_AUTHENTICATED.equals(media.accessModeOrDefault());
        boolean ownerDev = AppProperties.MEDIA_MODE_OWNER_DEV.equals(media.accessModeOrDefault());
        if (!anyAuthenticated && !ownerDev) {
            return null;
        }
        // 优先复用容器内已注册的 A 模式 bean（若 @ConditionalOnMissingBean 未退让）。
        try {
            for (MediaAccessPolicy candidate : applicationContext
                    .getBeansOfType(MediaAccessPolicy.class).values()) {
                if (candidate == this) {
                    continue;
                }
                if (anyAuthenticated && candidate instanceof AllowAuthenticatedMediaAccessPolicy) {
                    return candidate;
                }
                if (ownerDev && candidate instanceof OwnerBasedMediaAccessPolicy) {
                    return candidate;
                }
            }
        } catch (RuntimeException ignored) {
            // 容器查询失败时回退到构造；不在此记录标识性内容。
        }
        return anyAuthenticated
                ? new AllowAuthenticatedMediaAccessPolicy()
                : new OwnerBasedMediaAccessPolicy();
    }

