        UUID assessmentId = seedAssessment(gimbal.id(), memberId, "report_ready",
                publicMediaIds(mediaId), 1L, "{}");
        seedMedia(mediaId, MediaPurpose.ASSESSMENT_RESULT, "available", assessmentId, 1L, memberId,
