        // (d) report_payload 存在但不含该 mediaId
        UUID notReferenced = UUID.randomUUID();
        UUID assessmentNotRef = seedAssessment(gimbalId, memberId, "report_ready",
                "{\"schema_version\":1,\"public_media_ids\":[]}", 1L, "{}");
        seedMedia(notReferenced, MediaPurpose.ASSESSMENT_RESULT, "available", assessmentNotRef, 1L,
                memberId, "app", uploader, PNG);
        assertNotVisible(token, notReferenced);

        // (e) deny-by-default 判别力：photos[].public=false → 404；翻成 true 后同一请求 → 200
        UUID discriminated = UUID.randomUUID();
        UUID assessmentDisc = seedAssessment(gimbalId, memberId, "report_ready",
