package cn.yuanxin.mvp.web.mediapolicy;

import cn.yuanxin.mvp.web.media.MediaPurpose;
import cn.yuanxin.mvp.web.media.StoragePort;
import cn.yuanxin.mvp.web.support.AbstractWebIT;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.web.servlet.MvcResult;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;

/**
 * dev/test {@code app.media.access-mode=owner-dev} 下 B @Primary 策略的委派边界：
 * 非 face 用途且业务判定 false 时委派给 A 的上传者便利策略（保持 A 测试全绿）；
 * <b>face 用途永不委派</b>，即使便利模式开启也拒绝。与 A 的
 * {@code OwnerDevMediaAccessIT} 使用同一测试属性（共享 Spring 上下文）。
 */
@TestPropertySource(properties = "app.media.access-mode=owner-dev")
class MediaPolicyDelegationIT extends AbstractWebIT {

    private static final byte[] PNG = "PNG-DELEGATION-BYTES".getBytes(StandardCharsets.UTF_8);

    @Autowired
    JdbcTemplate jdbc;

    @Autowired
    StoragePort storagePort;

    private UUID seedMedia(UUID id, MediaPurpose purpose, String uploaderRef) {
        String objectKey = "test/" + purpose.dbValue() + "/" + id;
        storagePort.put(objectKey, new ByteArrayInputStream(PNG), PNG.length, "image/png");
        jdbc.update("INSERT INTO media_objects (id, bucket, object_key, purpose, member_id,"
                        + " uploader_type, uploader_ref, state, content_type, byte_size, content_hash,"
                        + " storage_metadata)"
                        + " VALUES (?, 'mvp-a-test', ?, ?, NULL, 'app', ?, 'available', 'image/png', ?, ?,"
                        + " '{\"schema_version\":1}'::jsonb)",
                id, objectKey, purpose.dbValue(), uploaderRef, (long) PNG.length, sha256Hex(PNG));
        return id;
    }

    @Test
    @DisplayName("owner-dev：非 face 且无业务归属 → 委派 A 便利策略放行上传者；face 用途永不委派")
    void ownerDevDelegatesNonFaceButNeverFace() throws Exception {
        String installationId = "inst-del-" + UUID.randomUUID().toString().substring(0, 8);
        LoginResult owner = loginAppWithInstallation(newPhone(), installationId);
        UUID accountId = UUID.fromString(owner.accountId());
        String uploaderRef = accountId + ":" + installationId;

        // 非 face：无 T05/T02 归属，业务判定 false → 委派 owner-dev 便利 → 上传者 200
        UUID nonFace = seedMedia(UUID.randomUUID(), MediaPurpose.ASSESSMENT_RESULT, uploaderRef);
        MvcResult delegated = mockMvc.perform(get("/api/v1/media/" + nonFace + "/content")
                        .header("Authorization", "Bearer " + owner.accessToken()))
                .andReturn();
        assertEquals(200, delegated.getResponse().getStatus(),
                delegated.getResponse().getContentAsString());
        assertArrayEquals(PNG, delegated.getResponse().getContentAsByteArray());

        // face：即使上传者也绝不委派 → 404
        UUID face = seedMedia(UUID.randomUUID(), MediaPurpose.GRANT_FACE, uploaderRef);
        MvcResult denied = mockMvc.perform(get("/api/v1/media/" + face + "/content")
                        .header("Authorization", "Bearer " + owner.accessToken()))
                .andReturn();
        assertEquals(404, denied.getResponse().getStatus(), denied.getResponse().getContentAsString());
    }

    private static String sha256Hex(byte[] bytes) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }
